from __future__ import annotations

import csv

import numpy as np
import pytest

from cohorts import ARTIFACT_PATH, build, write_csv
from gen import CHURN_P, N_COHORTS, N_USERS, generate


@pytest.fixture(scope="module")
def data():
    return generate()


@pytest.fixture(scope="module")
def tri(data):
    users, events = data
    return build(users, events)


@pytest.fixture(scope="module")
def artifact(tri):
    return write_csv(tri)


# --- retention -----------------------------------------------------------

def test_retention_at_offset_zero_is_one(tri):
    for c in range(N_COHORTS):
        assert tri["retention"][c][0] == pytest.approx(1.0)


def test_retention_nonincreasing(tri):
    for c in range(N_COHORTS):
        r = tri["retention"][c]
        assert np.all(np.diff(r) <= 1e-12), f"cohort {c} retention increased"


def test_triangle_is_properly_ragged(tri):
    assert len(tri["retention"]) == N_COHORTS
    assert len(tri["observed_offsets"]) == N_COHORTS
    for c in range(N_COHORTS):
        expected = N_COHORTS - c  # cohort c has exactly 12-c observable offsets
        assert len(tri["retention"][c]) == expected
        assert list(tri["observed_offsets"][c]) == list(range(expected))


# --- revenue -------------------------------------------------------------

def test_revenue_conservation_exact(data, tri):
    users, events = data
    total_direct = int(events["revenue_cents"].sum())
    total_triangle = sum(int(curve.sum()) for curve in tri["ltv_cum_cents"])
    assert isinstance(total_triangle, int)
    assert total_triangle == total_direct
    assert total_direct > 0


def test_ltv_curves_nondecreasing(tri):
    for c in range(N_COHORTS):
        ltv = tri["ltv_cum_cents"][c]
        assert np.all(np.diff(ltv) >= 0), f"cohort {c} LTV decreased"


# --- statistical sanity vs geometric survival ----------------------------

def test_month1_retention_near_geometric_survival(tri):
    curves = [r[1] for r in tri["retention"] if len(r) > 1]
    overall = float(np.mean(curves))
    target = 1.0 - CHURN_P
    assert abs(overall - target) <= 0.02, (
        f"month-1 retention {overall:.4f} not within 2pp of {target:.4f}"
    )


def test_population_size(data):
    users, _ = data
    assert len(users) == N_USERS
    counts = np.bincount(users["cohort"], minlength=N_COHORTS)
    assert counts.sum() == N_USERS
    assert (counts > 0).all()


# --- CSV artifact ---------------------------------------------------------

def test_csv_artifact_header_and_rows(artifact):
    with open(artifact, newline="") as fh:
        rows = list(csv.reader(fh))
    header = rows[0]
    assert header[:2] == ["cohort", "n_users"]
    assert header[2:] == [f"k{k:03d}" for k in range(N_COHORTS)]
    body = rows[1:]
    assert len(body) == N_COHORTS
    for i, row in enumerate(body):
        assert row[0] == str(i)
        # raggedness visible in the artifact: cohort i fills exactly 12-i cells
        filled = sum(1 for cell in row[2:] if cell != "")
        assert filled == N_COHORTS - i
